+    return SessionRepairReport(
+      path: path,
+      recordsRead: recordsRead,
+      recordsKept: recordsKept,
+      droppedByType: droppedByType,
+      keptLatestByType: keptLatestCounts,
+      bytesBefore: bytesBefore,
+      bytesAfter: bytesBefore,
+      backupPath: '$path.bak',
+      dryRun: true,
+    );
+  }
