+      'cannot back up $path to $backupPath: ${backup.errorOrNull!.message}',
+      code: SessionRepairErrorCode.unknown,
+    );
+  }
+  final swap = await renamable.renamePath(tempPath, path);
+  if (swap.isErr) {
