+
+void _appendSpan(List<(int, int)> spans, (int, int) span) {
+  if (spans.isNotEmpty && spans.last.$2 == span.$1) {
+    final (start, _) = spans.removeLast();
+    spans.add((start, span.$2));
+  } else {
+    spans.add(span);
+  }
