+            .where((t) => t == 'custom'),
+        isEmpty,
+        reason: 'the ledger records are gone',
+      );
+      expect((await fs.exists('${metadata.path}.bak')).getOrThrow(), isTrue);
+    });
+
+    test('--dry-run counts without writing', () async {
