+      final code = await runSessionRepairCliCommand(
+        write: io.write,
+        writeln: io.writeln,
+        env: fs,
+        sessionRoot: '/sessions',
+        sessionId: 'dry-run-me',
+        dryRun: true,
+      );
+      expect(code, 0);
+      expect(io.buffer.toString(), contains('would repair'));
+      expect(io.buffer.toString(), contains('dry run: nothing written'));
