+      final io = _RepairIo();
+      final code = await runSessionRepairCliCommand(
+        write: io.write,
+        writeln: io.writeln,
+        env: fs,
+        sessionRoot: '/sessions',
+        sessionId: metadata!.path,
+      );
+      expect(code, 0);
+      expect(io.buffer.toString(), contains('repaired'));
+      expect(
+        (await fs.exists('${metadata.path}.bak')).getOrThrow(),
