+  required void Function(String text) write,
+  required void Function(String text) writeln,
+  required FileSystem env,
+  required String sessionRoot,
+  String? sessionId,
+  bool dryRun = false,
+  SessionPresenceStore? presenceStore,
+}) async {
+  final target = sessionId?.trim() ?? '';
