+      writeln(
+        'session repair: session ${liveRow.sessionId} is live (pid '
+        '${liveRow.pid ?? 'unknown'}, heartbeat ${liveRow.touchedAt}) — '
+        'stop the owning process first.',
+      );
+      return 1;
+    }
+  } else {
+    final repo = JsonlSessionRepo(fs: env, sessionsRoot: sessionRoot);
