+      final io = _RepairIo();
+      final code = await runSessionRepairCliCommand(
+        write: io.write,
+        writeln: io.writeln,
+        env: fs,
+        sessionRoot: '/sessions',
+        sessionId: 'nope',
+      );
+      expect(code, 1);
+      expect(io.buffer.toString(), contains('not found'));
+    });
+  });
+}
