+    writeln('usage: fa session repair <sessionId|path> [--dry-run]');
+    return 1;
+  }
+  String? path;
+  if (target.endsWith('.jsonl')) {
+    final exists = await env.exists(target);
+    if (exists.isErr || !exists.valueOrNull!) {
+      writeln('session repair: no such file: $target');
+      return 1;
+    }
