+    );
+    for (var i = 0; i < 5; i++) {
+      await session.appendCustomEntry(
+        customType: 'model_request_summary',
+        data: {'n': i, 'pad': 'p' * 5000},
+      );
+    }
+    await session.appendMessage(UserMessage.text('keep me'));
+  }
