+    test('repairs by session id and reports the ledger surgery', () async {
+      await seedSession('repair-me');
+      final io = _RepairIo();
+      final code = await runSessionRepairCliCommand(
+        write: io.write,
+        writeln: io.writeln,
+        env: fs,
+        sessionRoot: '/sessions',
+        sessionId: 'repair-me',
+      );
