+
+void main() {
+  late List<Map<String, dynamic>> snapshots;
+
+  SubagentManager buildManager() {
+    snapshots = [];
+    return SubagentManager(
+      parentSessionId: 'parent',
+      sink: (rows) async => snapshots.add({
+        for (final row in rows) row['id'] as String: row,
+      }),
+      source: () async => const [],
+    );
+  }
